def transform(grid):
    if not grid:
        return grid

    rows, cols = len(grid), len(grid[0])

    # Find divider (must be complete row or column of ONE non-zero value)
    divider_r = None
    divider_c = None

    for r in range(rows):
        if rows > 0:
            val = grid[r][0]
            if val != 0 and all(grid[r][c] == val for c in range(cols)):
                divider_r = r
                break

    for c in range(cols):
        if cols > 0:
            val = grid[0][c]
            if val != 0 and all(grid[r][c] == val for r in range(rows)):
                divider_c = c
                break

    # Apply transformation
    if divider_r is not None:
        # Horizontal divider - take THE ORIGINAL top portion
        new_rows = divider_r
        return [[2 if grid[r][c] != 0 else 0 
                for c in range(cols)] 
               for r in range(new_rows)]
    elif divider_c is not None:
        # Vertical divider - take the LEFT portion
        new_cols = divider_c
        return [[2 if grid[r][c] != 0 else 0 
                for c in range(new_cols)] 
               for r in range(rows)]
    else:
        # No divider found - this is tricky
        # Maybe take first column only (as a side extraction)
        return [[grid[r][0] for r in range(rows)] if cols > 0 else grid]
